const pb = global.get("pb");

msg.payload.forEach(entry => {
    pb.addToMasterLog(entry, "delivered");
});

return msg;

const pb = global.get("pb");
const existing = pb.getMasterLog();
const existingIds = new Set(existing.map(e => e.id + "_" + (e.connection_id || "")));

const dupes = msg.payload.filter(e => existingIds.has(e.id + "_" + (e.connection_id || "")));
msg.payload = msg.payload.filter(e => !existingIds.has(e.id + "_" + (e.connection_id || "")));

if (dupes.length > 0) {
    node.warn({ msg: "Duplicate entries removed", duplicates: dupes });
}

return msg;
